function PageShell({ eyebrow, title, description, children }) {
  return (
    <section className="page-view">
      <div className="page-header">
        <span className="eyebrow">{eyebrow}</span>
        <h1>{title}</h1>
        <p>{description}</p>
      </div>

      <div className="page-content">{children}</div>
    </section>
  );
}

function App() {
  const [showWorkspace, setShowWorkspace] = useState(false);
  const [activePage, setActivePage] = useState("overview");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isLightMode, setIsLightMode] = useState(false);

  if (!showWorkspace) {
    return <LandingPage onEnterWorkspace={() => setShowWorkspace(true)} />;
  }

  const activeMenu = menuItems.find((item) => item.id === activePage);

  const renderPage = () => {
    switch (activePage) {
      case "guide":
        return <GuidePage />;
      case "documents":
        return <DocumentsPage />;
      case "questions":
        return <QuestionsPage />;
      case "pyq":
        return <PYQPage />;
      case "quiz":
        return <QuizPage />;
      case "exam":
        return <ExamPage />;
      case "planner":
        return <PlannerPage />;
      default:
        return <Overview setActivePage={setActivePage} />;
    }
  };

  return (
    <div className={`app-shell ${isLightMode ? "light-mode" : ""}`}>

      <button
  className="workspace-menu-toggle"
  onClick={() => setSidebarOpen(!sidebarOpen)}
  aria-label="Toggle workspace menu"
>
  <span />
  <span />
  <span />
</button>

      <aside className={`sidebar ${sidebarOpen ? "sidebar-open" : ""}`}>
        <div className="brand">
          <div className="brand-mark">S</div>

          <div>
            <strong>SUBJECT GUIDE</strong>
            <span>AI LEARNING SYSTEM</span>
          </div>
        </div>

        <div className="system-status">
          <span className="status-dot" />
          AI SYSTEM ONLINE
        </div>

        <nav className="nav-menu">
          {menuItems.map((item) => (
            <button
              key={item.id}
              className={`nav-item ${
                activePage === item.id ? "active" : ""
              }`}
              onClick={() => setActivePage(item.id)}
            >
              <span className="nav-icon">{item.icon}</span>
              <span>{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="sidebar-footer">
          <span>LOCAL AI</span>
          <span>RAG CORE</span>
          <span>v0.1</span>
        </div>
      </aside>

      <main className="main-area">
        <header className="topbar">
          <div>
            <span className="topbar-label">STUDENT INTELLIGENCE WORKSPACE</span>
            <strong>{activeMenu?.label}</strong>
          </div>

          <div className="topbar-user">
            <button className="theme-toggle" onClick={() => setIsLightMode(prev => !prev)} aria-label="Toggle theme"><span className="theme-icon"></span></button>
            <span className="grounded-badge">GROUNDED</span>
            <div className="avatar">SK</div>
          </div>
        </header>

        {renderPage()}
      </main>
    </div>
  );
}

export default App;
























